procedure PhysioReminder {
  about "Remind patients about their sessions"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  trigger when requested(days: Number)

  let all = fetch Sessions
  let due = filter all where status == "booked" and days_between(session_at, today()) <= days
  for each r in due up to 100 {
    let m = draft sms to r.patient: "Hi {r.patient default 'there'}, your session is in two days. Please remind me."
    let ok = request approval of m from owner timeout 2 hours else stop "batch not approved"
    send ok
  }
}
