procedure DrivingOffers {
  about "Offer new lesson packages to learners"
  policy DrivingPolicy
  sheet Learners "Learners" { learner: Text, phone: Phone, lessons_left: Number, test_date: Date, status: Text, license_no: Text private }
  trigger when Monday at 10am

  let all = fetch Learners
  let learners = filter all where lessons_left >= 2 and status == "active"
  let n = summarize count of learners
  append Learners { learner: "there", lessons_left: 0, test_date: Date, status: "active", license_no: Text }
  let msgs = draft each r in learners up to 25 sms to r.phone: "Hi {r.learner}, offer new lesson package for {r.lessons_left} lessons."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
}

