procedure LearnerStatus {
  about "Get learner status"
  policy DrivingPolicy
  sheet Learners "Learners" { learner: Text, phone: Phone, lessons_left: Number, test_date: Date, status: Text, license_no: Text private }
  trigger when requested(name: Text)

  let learners = fetch Learners
  let learner = filter learners where name == requested(name)
  if learner.length == 0 {
    notify owner "No learner found with name {requested(name)}"
    stop "no learner found"
  }
  let lessons = filter learner where lessons_left > 0
  let lessons_left = summarize count of lessons
  let test_date = filter learner where test_date != null
  let test_date = summarize count of test_date
  let m = draft sms to learner.phone: "Hi {learner.default 'there'}, how many lessons do you have left? {lessons_left}. Your test date is {test_date}."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}

