procedure DrivingStats {
  about "Count learners passed in the last 31 days"
  policy DrivingPolicy
  sheet Learners "Learners" { learner: Text, phone: Phone, lessons_left: Number, test_date: Date, status: Text, license_no: Text private }
  sheet Stats "Stats" { day: Date, passed: Number }

  let today = today()
  let last_31_days = filter Learners where test_date >= today() - 31 days and status == "passed"
  let n = summarize count of last_31_days
  append Stats { day: today(), passed: n }
  let m = draft sms to Learners phone: "Hi {learner default 'there'}, your stats show {n} learners passed in the last 31 days."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
```

