procedure CoffeeOrder {
  about "Place a house blend order"
  policy CoffeePolicy
  sheet Beans "Beans" { blend: Text, bags: Number, reorder_at: Number, order_bags: Number, roaster: Text, price_per_bag: Money }
  trigger when requested(order_bags: Number)

  if order_bags > 40 {
    notify owner "Order request {order_bags} exceeds the maximum order capacity."
    stop "order limit exceeded"
  }
  if !exists Beans { notify owner "No beans available in the Beans sheet." stop "no beans available"}
  let m = draft sms to Beans.roaster: "Hi {Beans.patient default 'there'}, your order of {order_bags} bags of the {Beans.blend} blend has been placed."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
