procedure HardwareOrders {
  about "Notify customers about special orders"
  policy HardwarePolicy
  sheet SpecialOrders "SpecialOrders" { order_no: Text, customer: Text, phone: Phone, item: Text, ordered_on: Date, arrived: Bool, paid: Money, status: Text }
  trigger when requested(days: Number)

  if days_between(ordered_on, today()) > 30 {
    notify owner "Special order {r.order_no} is older than 30 days."
    stop "outside order window"
  }
  if r.status != "waiting" {
    notify owner "Special order {r.order_no} is {r.status}, please wait."
    stop "waiting order"
  }
  if r.arrived == false {
    notify owner "There is no order for {r.customer} at this time."
    stop "no order available"
  }
