procedure WashToday {
  about "Count cars washed and those that went through bay B"
  policy WashPolicy
  sheet WashLog "WashLog" { plate: Text, washed_at: DateTime, bay: Text }
  trigger at 9pm

  let all = fetch WashLog
  let bay_washes = filter all where bay == "B"
  let bay_washes_count = summarize count of bay_washes
  let bay_washes_total = summarize sum of washed_at
  let bay_washes_per_bay = bay_washes_count / bay_washes_total
  let bay_washes_per_bay_string = format("{bay_washes_per_bay:.2f}", bay_washes_per_bay)
  let bay_washes_string = format("{bay_washes_count} cars washed in {bay_washes_total} minutes.")
  let bay_washes_string = format("{bay_washes_per_bay_string} ({bay_washes_string})", bay_washes_per_bay_string)
  let bay_washes_string = format("{bay_washes_string} ({bay_washes_string})", bay_washes_string)
