procedure OptomExam {
  about "Handle exam cancellations"
  policy OptomPolicy
  sheet Cancellations "Cancellations" { event_id: Text, slot_text: Text }
  trigger when new row r in Cancellations

  if r.status == "cancelled" {
    let e = fetch Exam
    let w = filter e where e.event_id == r.event_id
    let j = min(w.joined, today())
    if j == 0 {
      notify owner "There is no one waiting for this exam."
      stop "no waitlist"
    }
    let p = fetch Patient
    let s = filter p where p.patient == r.patient
    if s.length == 0 {
      notify owner "There is no patient waiting for this exam."
      stop "no patient"
    }
    let m = draft sms to r.phone: "Hi {p.name default 'there'}, your exam has been cancelled. Please call us for the time."
    let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
    send ok
    update e set status = "offered"
    let w = filter e where e.event_id == r.event_id
    let j = min(w.joined, today())
    if j == 0 {
      notify owner "There is no one waiting for this exam."
      stop "no waitlist"
    }
    let p = fetch Patient
    let s = filter p where p.patient == r.patient
    if s.length == 0 {
      notify owner "There is no patient waiting for this exam."
      stop "no patient"
    }
    let m = draft sms to r.phone: "Hi {p.name default 'there'}, your exam has been offered. Please call us for the time."
    let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
    send ok
  }
}
