  about "On request, contact recent cancelled calls"
  policy PlumbingPolicy
  sheet Calls "Calls" { customer: Text, phone: Phone, visit_at: DateTime, status: Text, invoice: Money, alarm_code: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Calls
  let targets = filter all where status == "booked" and days_between(visit_at, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  let msgs = draft each r in targets up to 20 sms to r.phone: "Hi {r.customer default 'there'}, come back to the clinic! Use code RETURN20 on your next visit."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
}

procedure VetOverdueNotifications {
  about "Notify pet owners about overdue pets"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger when requested(days: Number)

  let all = fetch Pets
  let overdue = filter all where days_between(vaccine_due, today()) <= days and status == "overdue"
  let n = summarize count of overdue
  append Pets { owner: today(), phone: vaccine_due, status: "overdue", balance: n }
  let msgs = draft each r in overdue up to 50 sms to r.phone: "Hi {r.owner default 'there'}, your pet {r.name} is overdue. Please contact me on {time_of(r.vaccine_due)}."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
}

