procedure FloristOrder {
  about "Order flowers based on stock and supplier"
  policy FloristStockPolicy
  sheet Flowers "Flowers" { flower: Text, stems: Number, minimum: Number, reorder_qty: Number, grower: Text, unit_cost: Money }

  let all = fetch Flowers
  let min_stock = min(stems, minimum)
  let reorder_amount = min_stock * reorder_qty
  let order_limit = 2
  let order_count = 0

  for each r in all up to order_limit {
    if r.minimum > min_stock {
      let m = draft sms to r.grower: "Hi {r.flower}, we have {min_stock} stems left. Order {r.stems} stems."
      let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
      send ok
      order_count += 1
    }
  }

  if order_count < order_limit {
    notify owner "No flowers available for order."
  }
}
